import { Feed } from "feed";
import { Page, SiteConfig } from "./types";
import path from "path";

export function generateRss(pages: Page[], config: SiteConfig): string {
  const published = pages.filter(p => !p.frontmatter.draft && p.frontmatter.date);
  published.sort((a, b) => new Date(b.frontmatter.date!).getTime() - new Date(a.frontmatter.date!).getTime());

  const feed = new Feed({
    title: config.siteName,
    description: config.siteName,
    id: config.siteUrl,
    link: config.siteUrl,
    language: "en",
    updated: published.length > 0 ? new Date(published[0].frontmatter.date!) : new Date(),
    copyright: `All rights reserved ${new Date().getFullYear()}`,
    author: config.author ? { name: config.author } : undefined,
  });

  for (const p of published.slice(0, 50)) {
    feed.addItem({
      title: p.frontmatter.title || path.basename(p.sourcePath, ".md"),
      id: config.siteUrl.replace(/\/$/, "") + p.path,
      link: config.siteUrl.replace(/\/$/, "") + p.path,
      date: new Date(p.frontmatter.date!),
      content: p.html,
    });
  }

  return feed.rss2();
}

import http from "http";
import fs from "fs";
import path from "path";
import { WebSocketServer, WebSocket } from "ws";
import chokidar from "chokidar";
import { GeneratorOptions } from "./types";
import { buildSite } from "./generator";

const LIVE_RELOAD_SCRIPT = `
<script>
(function() {
  var ws = new WebSocket('ws://' + location.host + '/__livereload');
  ws.onmessage = function(msg) {
    if (msg.data === 'reload') location.reload();
  };
})();
</script>
`;

export function startDevServer(options: GeneratorOptions): void {
  const watchPaths = [options.sourceDir, options.templateDir];

  buildSite(options);

  const server = http.createServer((req, res) => {
    const url = req.url || "/";
    const filePath = url === "/"
      ? path.join(options.outputDir, "index.html")
      : path.join(options.outputDir, url);

    try {
      let content = fs.readFileSync(filePath, "utf-8");

      // For HTML files inject the livereload script before </body>
      if (filePath.endsWith(".html") && content.includes("</body>")) {
        content = content.replace("</body>", LIVE_RELOAD_SCRIPT + "</body>");
      } else if (filePath.endsWith(".html")) {
        content += LIVE_RELOAD_SCRIPT;
      }

      const mime: Record<string, string> = {
        ".html": "text/html",
        ".css": "text/css",
        ".js": "application/javascript",
        ".json": "application/json",
        ".png": "image/png",
        ".jpg": "image/jpeg",
        ".svg": "image/svg+xml",
        ".xml": "application/xml",
      };
      const ext = path.extname(filePath);
      res.writeHead(200, { "Content-Type": mime[ext] || "text/plain" });
      res.end(content);
    } catch {
      res.writeHead(404);
      res.end("Not found");
    }
  });

  const wss = new WebSocketServer({ server });
  const clients = new Set<WebSocket>();

  wss.on("connection", (ws) => {
    clients.add(ws);
    ws.on("close", () => clients.delete(ws));
  });

  function broadcastReload() {
    for (const ws of clients) {
      ws.send("reload");
    }
  }

  const watcher = chokidar.watch(watchPaths, {
    ignoreInitial: true,
    awaitWriteFinish: { stabilityThreshold: 300 },
  });

  watcher.on("all", () => {
    try {
      buildSite(options);
      broadcastReload();
    } catch (err) {
      console.error("Build error:", err);
    }
  });

  const port = 3456;
  server.listen(port, () => {
    console.log(`Dev server running at http://localhost:${port}`);
    console.log(`Watching ${options.sourceDir} and ${options.templateDir} for changes`);
  });
}

import fs from "fs";
import path from "path";
import { GeneratorOptions, Page } from "./types";
import { collectMarkdownFiles, parseFrontmatter, deriveUrlPath } from "./parser";
import { configureTemplateEngine, renderPage, buildTagMap, generateTagIndex } from "./renderer";
import { configureMarked, markdownToHtml } from "./highlight";
import { generateRss } from "./rss";

export function buildSite(options: GeneratorOptions): void {
  configureMarked();

  const layout = configureTemplateEngine(options.templateDir);
  const markdownFiles = collectMarkdownFiles(options.sourceDir);

  const pages: Page[] = [];
  for (const f of markdownFiles) {
    const { frontmatter, content } = parseFrontmatter(f);
    const urlPath = deriveUrlPath(f, options.sourceDir);
    const html = markdownToHtml(content);
    pages.push({ path: urlPath, sourcePath: f, frontmatter, content, html });
  }

  // Print summary
  const drafts = pages.filter(p => p.frontmatter.draft);
  const published = pages.filter(p => !p.frontmatter.draft);
  console.log(`Found ${pages.length} pages (${published.length} published, ${drafts.length} drafts)`);

  // Ensure output directory exists
  if (fs.existsSync(options.outputDir)) {
    fs.rmSync(options.outputDir, { recursive: true });
  }
  fs.mkdirSync(options.outputDir, { recursive: true });

  // Render each published page
  for (const p of published) {
    const rendered = renderPage(p, pages, options.templateDir, layout, options);
    writeOutput(options.outputDir, p.path, rendered);
    console.log(`  -> ${p.path}`);
  }

  // Tag index pages
  const tagMap = buildTagMap(published);
  for (const [tag, taggedPages] of tagMap) {
    const rendered = generateTagIndex(tag, taggedPages, layout, options);
    const tagPath = `/tags/${slugify(tag)}/`;
    writeOutput(options.outputDir, tagPath, rendered);
    console.log(`  -> ${tagPath} (${taggedPages.length} pages)`);
  }

  // RSS feed
  const rss = generateRss(published, options.config);
  writeOutput(options.outputDir, "/feed.xml", rss);
  console.log(`  -> /feed.xml`);
}

function writeOutput(outDir: string, urlPath: string, html: string): void {
  // Normalize: remove leading /, treat trailing / as index.html
  let rel = urlPath.replace(/^\/+/, "");
  if (!rel || rel.endsWith("/")) {
    rel = rel + "index.html";
  }
  const outPath = path.join(outDir, rel);
  const dir = path.dirname(outPath);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(outPath, html);
}

function slugify(tag: string): string {
  return tag.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

